  "Automatic (recommended)": "تلقائي (موصى به)",
  "Automatic plays Dolby Vision through the TV player, which switches the screen into Dolby Vision itself, and keeps HDR10 and HLG on the built-in player for its steadier buffering.  Choose TV player for all HDR if HDR pictures look washed out or grey.": "يشغّل الوضع التلقائي Dolby Vision عبر مشغّل التلفزيون، الذي يحوّل الشاشة إلى Dolby Vision بنفسه، ويُبقي HDR10 وHLG على المشغّل المدمج لأن تخزينه المؤقت أكثر ثباتًا.  اختر مشغّل التلفزيون لكل محتوى HDR إذا بدت صور HDR باهتة أو رمادية.",
  "Automatic uses the built-in demuxer for fine buffer control and falls back to the TV player when a server blocks it.  TV player uses the least CPU but ignores buffer settings.": "يستخدم الوضع التلقائي demuxer المدمج للتحكم الدقيق في التخزين المؤقت، ويعود إلى مشغّل التلفزيون عندما يحظره الخادم.  مشغّل التلفزيون يستهلك أقل قدر من المعالج لكنه يتجاهل إعدادات التخزين المؤقت.",
  "Automatic uses the network helper: a part of TiviBro that runs in the background on the TV and fetches your channels, guide and streams for the app.  webOS needs it for most providers.  Direct asks the provider straight from the app, which only works with servers that allow it.  Channel lists still load through the helper when it runs, so a big one can't close TiviBro.": "يستخدم الوضع التلقائي مساعد الشبكة: جزء من TiviBro يعمل في الخلفية على التلفزيون ويجلب قنواتك والدليل والبث للتطبيق.  يحتاج إليه webOS مع معظم المزوّدين.  الاتصال المباشر يسأل المزوّد من التطبيق مباشرةً، ولا يعمل إلا مع الخوادم التي تسمح بذلك.  وتُحمَّل قوائم القنوات عبر المساعد متى كان يعمل، فلا تتسبب قائمة كبيرة في إغلاق TiviBro.",
  "Automatic, in Dolby Vision": "تلقائي، في Dolby Vision",
