  "Away from home, Plex plays video only when you or the server's owner have Plex Pass (or a Remote Watch Pass).  At home it's free.": "خارج المنزل، لا يشغّل Plex الفيديو إلا إذا كان لديك أو لدى مالك الخادم Plex Pass (أو Remote Watch Pass).  في المنزل هو مجاني.",
