  "Empty removes it.  Typing is easier from the phone app.": "اتركه فارغًا لإزالته.  الكتابة أسهل من تطبيق الهاتف.",
  "Empty signs out.": "اتركه فارغًا لتسجيل الخروج.",
  "Empty this group": "إفراغ هذه المجموعة",
  "Enable recommended defaults": "تفعيل الإعدادات الافتراضية الموصى بها",
  "End credits marked the same way.  Skipping them brings up Up next with its countdown (the next episode, or the next movie of a collection you play), jumps to a scene after the credits, or ends the movie.  Automatically: only in the last quarter of a movie or episode.": "تُحدَّد شارة النهاية بالطريقة نفسها.  تخطيها يعرض شاشة التالي مع العد التنازلي (الحلقة التالية، أو الفيلم التالي من سلسلة أفلام تشغّلها)، أو ينتقل إلى مشهد بعد الشارة، أو ينهي الفيلم.  تلقائي: فقط في الربع الأخير من الفيلم أو الحلقة.",
  "Ends {x}": "ينتهي {x}",
  "English": "الإنجليزية",
  "Enter a full http:// or https:// address.": "أدخل عنوانًا كاملًا يبدأ بـ http:// أو https://.",
  "Enter a show title.": "أدخل عنوان المسلسل.",
  "Enter a time in seconds, starting at zero.": "أدخل وقتًا بالثواني، بدءًا من الصفر.",
  "Enter a valid air date.": "أدخل تاريخ عرض صالحًا.",
  "Enter a valid episode number.": "أدخل رقم حلقة صالحًا.",
  "Enter a valid season.": "أدخل موسمًا صالحًا.",
  "Enter episode numbers such as 1,2.": "أدخل أرقام الحلقات مثل 1,2.",
  "Enter episode start": "أدخل بداية الحلقة",
  "Enter it again": "أدخلها مرة أخرى",
  "Enter the playlist address.": "أدخل عنوان قائمة التشغيل.",
  "Enter the portal address (starting with http) and the MAC address, like 00:1A:79:12:34:56.": "أدخل عنوان البوابة (يبدأ بـ http) وعنوان MAC، مثل 00:1A:79:12:34:56.",
  "Enter the server's name or IP address, like NAS or 192.168.1.20.": "أدخل اسم الخادم أو عنوان IP، مثل NAS أو 192.168.1.20.",
  "Enter the server's name or IP address.": "أدخل اسم الخادم أو عنوان IP.",
  "Enter the server, username and password.": "أدخل الخادم واسم المستخدم وكلمة المرور.",
  "Enter your media folder's address and login, or use the web editor": "أدخل عنوان مجلد الوسائط وبيانات الدخول، أو استخدم محرر الويب",
  "Episode boundaries": "حدود الحلقات",
