  "Estonian": "الإستونية",
  "Even width": "عرض متساوٍ",
  "Even width lines up channel numbers and times and keeps the buffer info steady.  Fixed width also crosses the zero.": "العرض المتساوي يحاذي أرقام القنوات والأوقات ويثبّت معلومات المخزن المؤقت.  العرض الثابت يضع خطًا على الصفر أيضًا.",
  "Event channels": "قنوات الأحداث",
