  "Every channel uses the setting above": "كل القنوات تستخدم الإعداد أعلاه",
  "Every colour at once.  Your own mix: pick an accent and a background.": "كل الألوان دفعة واحدة.  مزيجك الخاص: اختر لونًا مميزًا وخلفية.",
  "Every colour at once: Black and white, Tokyo Night, Dracula, Nord, Gruvbox and more.  Your own mix: choose a background and an accent below.": "كل الألوان دفعة واحدة: أبيض وأسود، Tokyo Night، Dracula، Nord، Gruvbox والمزيد.  مزيجك الخاص: اختر خلفية ولونًا مميزًا أدناه.",
