  "Extras": "إضافات",
  "FFmpeg is unmodified, built from ffmpeg.org/releases/ffmpeg-7.1.1.tar.xz by scripts/ffmpeg/build.sh in TiviBro's repository.  It runs as a separate program, which you can replace with your own build.": "FFmpeg غير معدَّل، وقد بُني من ffmpeg.org/releases/ffmpeg-7.1.1.tar.xz بواسطة scripts/ffmpeg/build.sh في مستودع TiviBro.  يعمل كبرنامج منفصل يمكنك استبداله بنسختك الخاصة.",
