  "Favorite, details, episode order and more": "المفضلة والتفاصيل وترتيب الحلقات والمزيد",
  "Favorites also in lists": "المفضلة أيضًا في القوائم",
  "Favorites and your groups above the provider groups.": "المفضلة ومجموعاتك فوق مجموعات المزوّد.",
  "Fetch details for all": "جلب تفاصيل الكل",
  "Fetch missing details": "جلب التفاصيل الناقصة",
  "Fetch movie details from TMDB?  Titles and years or saved movie IDs are sent to TMDB.  Images load from image.tmdb.org.  Your source logins are never sent.": "جلب تفاصيل الأفلام من TMDB؟  تُرسل العناوين والسنوات أو معرّفات الأفلام المحفوظة إلى TMDB.  تُحمَّل الصور من image.tmdb.org.  لا تُرسل بيانات تسجيل دخول مصادرك أبدًا.",
  "Fetch movie details from TheTVDB?  Titles and years or saved movie IDs are sent to TheTVDB through TiviBro's service.  Images load from artworks.thetvdb.com.  Your source logins are never sent.": "جلب تفاصيل الأفلام من TheTVDB؟  تُرسل العناوين والسنوات أو معرّفات الأفلام المحفوظة إلى TheTVDB عبر خدمة TiviBro.  تُحمَّل الصور من artworks.thetvdb.com.  لا تُرسل بيانات تسجيل دخول مصادرك أبدًا.",
  "Fetch show details from TMDB?  Show names and years or saved show IDs are sent to TMDB.  Images load from image.tmdb.org.  Your source logins are never sent.": "جلب تفاصيل المسلسلات من TMDB؟  تُرسل أسماء المسلسلات وسنواتها أو معرّفات المسلسلات المحفوظة إلى TMDB.  تُحمَّل الصور من image.tmdb.org.  لا تُرسل بيانات تسجيل دخول مصادرك أبدًا.",
  "Fetch show details from TheTVDB?  Show names and years or saved show IDs are sent to TheTVDB through TiviBro's service.  Images load from artworks.thetvdb.com.  Your source logins are never sent.": "جلب تفاصيل المسلسلات من TheTVDB؟  تُرسل أسماء المسلسلات وسنواتها أو معرّفات المسلسلات المحفوظة إلى TheTVDB عبر خدمة TiviBro.  تُحمَّل الصور من artworks.thetvdb.com.  لا تُرسل بيانات تسجيل دخول مصادرك أبدًا.",
  "Fetching TV show details…": "جارٍ جلب تفاصيل المسلسلات…",
