  "High": "عالية",
  "Higher keeps the lines clear of a picture's own captions or a score bar.  For subtitles TiviBro draws (most of them); the TV's own keep their place.  Also in the player: Subtitles > Size and style.": "الأعلى يُبقي الأسطر بعيدة عن تعليقات الصورة نفسها أو شريط النتيجة.  للترجمة التي يرسمها TiviBro (معظمها)؛ أما ترجمة التلفزيون نفسه فتبقى في مكانها.  وهي متاحة أيضًا في المشغّل: الترجمة > الحجم والنمط.",
