  "Hold ◀  earlier": "اضغط مطولًا على ◀  أقدم",
  "Holds": "يحتفظ بـ",
  "Holds at most about 24 MB of video ahead (the full buffer profile on most channels, less on a heavy 4K one) so TiviBro doesn't close on TVs with 1 or 2 GB.  Automatic turns it on for TVs with 1 GB, and for a few days after TiviBro closed while playing.": "يحتفظ بحوالي 24 MB من الفيديو مسبقًا كحد أقصى (ملف المخزن المؤقت الكامل في معظم القنوات، وأقل في قناة 4K ثقيلة) حتى لا يُغلق TiviBro على التلفزيونات ذات 1 أو 2 GB.  تلقائي يشغّله للتلفزيونات ذات 1 GB، ولبضعة أيام بعد أن أُغلق TiviBro أثناء التشغيل.",
  "Holiday  ·": "عطلة  ·",
  "Holiday  ·  until": "عطلة  ·  حتى",
  "Home": "الرئيسية",
  "Home rows": "صفوف الرئيسية",
  "Home: the title you're on large at the top, with poster shelves (Continue watching, My list, Recently added, TMDB's lists of your provider's titles, and the categories you pin).  Green there opens all categories.  Categories: the list of categories, as before.": "الرئيسية: العنوان الذي أنت عليه بحجم كبير في الأعلى، مع رفوف الملصقات (متابعة المشاهدة، قائمتي، المضاف حديثًا، قوائم TMDB لعناوين مزوّدك، والفئات التي تثبّتها).  Green هناك يفتح كل الفئات.  الفئات: قائمة الفئات، كما كانت.",
  "How far into the guide to look.": "المدة التي يمتد إليها الدليل إلى الأمام.",
  "How it looks": "كيف يبدو",
  "How long a frozen picture is tolerated before the player recovers it.": "المدة التي يُسمح فيها بتجمّد الصورة قبل أن يستعيدها المشغّل.",
  "How much video to hold before and during playback.  More buffer means fewer freezes on shaky streams, but channels take a little longer to start.  Automatic learns from each provider: channels start fast where its streams are steady, and with a bigger cushion where they run dry.  A live channel only banks what the provider sends ahead of real time, often 10 to 40 seconds, so the bigger profiles mostly start safer rather than hold more.  Buffer info shows the most a channel has reached.": "مقدار الفيديو الذي يُحتفظ به قبل التشغيل وأثناءه.  المخزن الأكبر يعني تجمّدًا أقل في البث غير المستقر، لكن القنوات تستغرق وقتًا أطول قليلًا لتبدأ.  تلقائي يتعلّم من كل مزوّد: تبدأ القنوات بسرعة حيث تكون بثوثه مستقرة، وبمخزن أكبر حيث تنقطع.  القناة المباشرة لا تخزّن إلا ما يرسله المزوّد قبل الوقت الفعلي، وغالبًا من 10 إلى 40 ثانية، لذا تبدأ الخيارات الأكبر بشكل أكثر أمانًا في الغالب بدل أن تحتفظ بمقدار أكبر.  معلومات المخزن تعرض أقصى ما بلغته القناة.",
  "How phones show this TV.": "كيف تعرض الهواتف هذا التلفزيون.",
  "How see-through the info panel, quick menu and channel guide are in fullscreen.": "مدى شفافية لوحة المعلومات والقائمة السريعة ودليل القنوات في وضع ملء الشاشة.",
  "How soon a game has to start to be in the group.": "مدى قرب بدء المباراة لتدخل في المجموعة.",
  "How the guide shows programmes airing right now.": "كيف يعرض الدليل البرامج التي تُبث الآن.",
  "How the selected item stands out.  Outline adds a white ring, easier to spot from across the room.": "كيف يظهر العنصر المحدد بارزًا.  الإطار يضيف حلقة بيضاء، يسهل رؤيتها من آخر الغرفة.",
  "How times show everywhere in TiviBro: the guide, the info panel, reminders.  Automatic follows the TV's region.": "كيف تظهر الأوقات في كل مكان في TiviBro: الدليل ولوحة المعلومات والتذكيرات.  تلقائي يتبع منطقة التلفزيون.",
  "How your guide is built, in this order": "كيف يُبنى دليلك، بهذا الترتيب",
  "Hungarian": "المجرية",
  "I have an account": "لدي حساب",
  "I see my API key": "أرى مفتاح API الخاص بي",
  "If an update caused trouble.  Your settings and edits are saved first; recordings and your playlist aren't touched.": "إذا سبّب تحديث مشكلة.  تُحفظ إعداداتك وتعديلاتك أولًا، ولا تُمس التسجيلات ولا قائمة التشغيل.",
  "In each category, My list and the home's category shelves.  All movies and All shows are newest first in the provider's order.  Recently added is always newest first.  Red on the home too.": "في كل فئة، وفي قائمتي، وفي رفوف فئات الرئيسية.  كل الأفلام وكل المسلسلات تأتي الأحدث أولًا بترتيب المزوّد.  المضاف حديثًا الأحدث أولًا دائمًا.  Red في الرئيسية أيضًا.",
  "In fullscreen, Hold Red records, Hold Yellow pauses and Hold Blue shows stream info.  Hold Red records in the guide and lists too, and Hold Blue gives a show's details in the guide.  OK in fullscreen has them all as well.": "في ملء الشاشة، الضغط المطوّل على Red يسجّل، وعلى Yellow يوقف مؤقتًا، وعلى Blue يعرض معلومات البث.  الضغط المطوّل على Red يسجّل في الدليل والقوائم أيضًا، وعلى Blue يعرض تفاصيل البرنامج في الدليل.  OK في ملء الشاشة فيه كل ذلك أيضًا.",
  "In the TiviBro phone app": "في تطبيق TiviBro للهاتف",
  "In the app": "في التطبيق",
  "In the guide": "في الدليل",
  "In the guide, Hold OK on a programme and choose Record.  While watching, the quick menu has Record too.": "في الدليل، اضغط مطولًا على OK على برنامج واختر تسجيل.  وأثناء المشاهدة، تتضمن القائمة السريعة تسجيل أيضًا.",
  "In the guide, new episodes and episodes or movies that haven't aired yet (not news or sport), and on the Shows screen, episodes you haven't started, keep only their title, season and episode, and when they air: no summary, episode title or picture from the episode.": "في الدليل، الحلقات الجديدة والحلقات أو الأفلام التي لم تُعرض بعد (غير الأخبار والرياضة)، وفي شاشة المسلسلات، الحلقات التي لم تبدأها، تحتفظ بعنوانها وموسمها وحلقتها ووقت عرضها فقط: بلا ملخص ولا عنوان حلقة ولا صورة من الحلقة.",
  "In the network helper": "في مساعد الشبكة",
  "In the player": "في المشغّل",
  "In this order": "بهذا الترتيب",
  "In time, then early or late, then in time again: that subtitle was made for another cut of the film.  Try another download.": "متزامنة، ثم مبكرة أو متأخرة، ثم متزامنة من جديد: هذه الترجمة مصنوعة لنسخة أخرى من الفيلم.  جرّب تنزيلًا آخر.",
