  "It needs a Google Cloud service account that the drive or folder is shared with.  The web editor walks you through it.": "يحتاج إلى حساب خدمة في Google Cloud تتم مشاركة المحرك أو المجلد معه.  يرشدك محرر الويب خطوة بخطوة.",
