  "Its Recently added, Continue watching and favorites on My media's Home.  Off: only on the Movies and TV shows tabs.": "المضاف حديثًا ومتابعة المشاهدة والمفضلة في الصفحة الرئيسية ضمن وسائطي.  عند الإيقاف: في تبويبي أفلام ومسلسلات فقط.",
  "Its folder, Dropbox sign-in, pause or restart a scan.  On the phone: its own form.": "مجلده وتسجيل الدخول إلى Dropbox وإيقاف الفحص مؤقتًا أو إعادة تشغيله.  على الهاتف: في نموذج خاص به.",
