  "OK plays it here, OK again for fullscreen": "OK يشغّله هنا، OK مرة أخرى لملء الشاشة",
  "OK shows or hides a group.  Hold OK on one to move it.": "OK يُظهر المجموعة أو يخفيها.  اضغط مطولًا على OK لنقلها.",
  "OK to type a name": "OK لكتابة اسم",
  "OK turns a button on or off.  Hold OK on one to move it.  Buttons only appear when they apply: Audio needs two or more tracks, Record a USB drive or share.": "OK يشغّل الزر أو يوقفه.  اضغط مطولًا على OK لنقله.  لا تظهر الأزرار إلا عند الحاجة: الصوت يحتاج مسارين أو أكثر، وتسجيل يحتاج محرك USB أو مشاركة.",
  "Off": "إيقاف",
  "Off asks for the PIN every time.": "عند الإيقاف يُطلب الرمز PIN في كل مرة.",
  "Off keeps the list here without its shelf.": "عند الإيقاف تبقى القائمة هنا دون رفّها.",
  "Off or unreachable": "متوقف أو يتعذر الوصول إليه",
  "Off shows just the number and name.": "عند الإيقاف يظهر الرقم والاسم فقط.",
  "Off shows logos only, leaving more room.": "عند الإيقاف تظهر الشعارات فقط، فتتسع المساحة.",
  "Off, HDR10": "متوقف، HDR10",
  "On": "مفعّل",
  "On My media": "في وسائطي",
  "On Trakt": "على Trakt",
  "On a network share, a recording can be watched once its first 10 minutes are up there.  Yellow goes to the channel live.": "على مشاركة الشبكة، يمكن مشاهدة التسجيل بعد وصول أول 10 دقائق منه إليها.  يفتح Yellow القناة مباشرة.",
  "On now": "يُعرض الآن",
  "On now, score hidden": "يُعرض الآن، النتيجة مخفية",
  "On shelves that mix categories (Recently added, Continue watching, My list, TMDB's lists), each poster says which category it's in, after its year and rating.  Long names are cut short.": "في الأرفف التي تجمع فئات مختلفة (أضيف حديثًا، متابعة المشاهدة، قائمتي، قوائم TMDB)، يوضح كل ملصق فئته بعد السنة والتقييم.  تُقتطع الأسماء الطويلة.",
  "On the Channels screen": "في شاشة القنوات",
  "On the USB drive, in \"TiviBro Recordings\"": "على وحدة USB، في \"TiviBro Recordings\"",
  "On the drive: {x}": "على القرص: {x}",
  "On time": "في الوقت المحدد",
  "On your channels": "على قنواتك",
  "On your network": "على شبكتك",
  "On your phone or computer, open opensubtitles.com": "على هاتفك أو كمبيوترك، افتح opensubtitles.com",
  "On {x}": "على {x}",
  "On {x} and {n} more": ["على {x} و{n} أخرى", "على {x} و{n} أخرى", "على {x} و{n} أخرى", "على {x} و{n} قنوات أخرى", "على {x} و{n} قناة أخرى", "على {x} و{n} قناة أخرى"],
  "On, 4K too": "مفعّل، مع 4K أيضًا",
  "On, none here": "مفعّل، لا شيء هنا",
  "On: a favorite movie or show is in Favorites and also in Movies or TV shows.  Off: only in Favorites.": "مفعّل: الفيلم أو المسلسل المفضل يظهر في المفضلة وأيضًا في أفلام أو مسلسلات.  معطّل: يظهر في المفضلة فقط.",
  "On: the full guide was {x} {y}, and is corrected.": "مفعّل: كان الدليل الكامل {x} {y}، وتم تصحيحه.",
  "Once a day, and when a new version first starts, TiviBro says which version it is (and whether it is new or an update) and which webOS this TV has.  The count also notes the country it came from, to see which languages to add next.  Nothing else: no address is kept, no ID, nothing about your channels or playlists.": "مرة في اليوم، وعند بدء إصدار جديد لأول مرة، يذكر TiviBro رقم الإصدار (وهل هو جديد أم تحديث) وإصدار webOS في هذا التلفزيون.  يسجل العدّ أيضًا البلد الذي جاء منه، لمعرفة اللغات التي تُضاف لاحقًا.  لا شيء غير ذلك: لا يُحفظ عنوان، ولا معرّف، ولا شيء عن قنواتك أو قوائم التشغيل.",
  "One group with your stations, by city and network.": "مجموعة واحدة بمحطاتك، حسب المدينة والشبكة.",
  "One moment…": "لحظة…",
  "One movie after another, in order": "فيلم بعد آخر، بالترتيب",
  "One or two addresses, IPv4 or IPv6 (192.168.1.1, 2001:de4::101), or a DNS-over-HTTPS link (https://dns.example/dns-query).": "عنوان أو عنوانان، IPv4 أو IPv6 (192.168.1.1, 2001:de4::101)، أو رابط DNS-over-HTTPS (https://dns.example/dns-query).",
  "Online": "متصل",
  "Only for channels with no other guide.": "فقط للقنوات التي ليس لها دليل آخر.",
  "Only if your provider asks for a specific one.  Sent by the network helper for this playlist.": "فقط إذا طلب مزودك واحدًا محددًا.  يرسله مساعد الشبكة لقائمة التشغيل هذه.",
  "Only phones you pair here can connect.  The pairing code never crosses the network, and everything a phone sends is signed with a key only that phone and this TV have.": "لا يمكن إلا للهواتف التي تقترنها هنا أن تتصل.  لا يعبر رمز الاقتران الشبكة أبدًا، ويُوقَّع كل ما يرسله الهاتف بمفتاح لا يملكه إلا ذلك الهاتف وهذا التلفزيون.",
  "Only some parts out of time?": "هل بعض الأجزاء فقط غير متزامنة؟",
  "Only when I press Green": "فقط عند الضغط على Green",
  "Only your own lists will apply.": "ستُطبَّق قوائمك الخاصة فقط.",
  "Open": "فتح",
