  "OpenSubtitles didn't take that key.  Copy it again (the long code under API key) and paste it once more.": "لم يقبل OpenSubtitles هذا المفتاح.  انسخه مرة أخرى (الرمز الطويل تحت API key) والصقه من جديد.",
