  "Opening": "جارٍ الفتح",
  "Or hold OK on any channel and choose Assign guide.  A channel that will never have a guide: hold OK > No guide for this channel.": "أو اضغط مطولًا على OK على أي قناة واختر تعيين دليل.  لقناة لن يكون لها دليل أبدًا: اضغط مطولًا على OK > لا دليل لهذه القناة.",
