  "Pairing the TiviBro app is different: Settings > Phone app and web editor > Pair the TiviBro app.": "إقران تطبيق TiviBro يختلف: الإعدادات > تطبيق الهاتف ومحرر الويب > إقران تطبيق TiviBro.",
