  "Paste a list's link": "الصق رابط القائمة",
  "Paste these from the TiviBro phone app (Settings > API keys): a phone keyboard and copy and paste make it quick.": "الصقها من تطبيق TiviBro على الهاتف (الإعدادات > مفاتيح API): لوحة مفاتيح الهاتف مع النسخ واللصق تجعل الأمر سريعًا.",
  "Pastel": "باستيل",
  "Pause and rewind": "إيقاف مؤقت ورجوع",
  "Pause keeps the channel, and Play carries on from where you paused, with ◀ ▶ to go back and forth in it.  On a USB drive (a rooted TV) or a network share it keeps up to 2 hours; without either, up to 10 minutes in the TV's own storage.  Off: pause holds for as long as the player's buffer, then Play is live.": "يبقي الإيقاف المؤقت القناة محفوظة، ويتابع التشغيل من حيث توقفت، مع ◀ ▶ للتنقل داخلها للخلف والأمام.  على قرص USB (تلفزيون مُعدَّل الجذر) أو مشاركة شبكة يحفظ حتى ساعتين؛ وبدونهما يحفظ حتى 10 دقائق في مساحة التلفزيون نفسه.  عند الإيقاف: يستمر الإيقاف المؤقت بقدر مخزن المشغّل، ثم يصبح التشغيل مباشرًا.",
  "Pause live TV": "إيقاف البث المباشر مؤقتًا",
  "Pause scan": "إيقاف الفحص مؤقتًا",
  "Paused": "متوقف مؤقتًا",
  "Pay-per-view and league pass channels whose names carry the game and its time: read into the guide.": "قنوات الدفع مقابل المشاهدة وبطاقات الدوري التي تحمل أسماؤها المباراة وموعدها: تُقرأ إلى الدليل.",
  "Phone app and web editor": "تطبيق الهاتف ومحرر الويب",
  "Phone app connection": "اتصال تطبيق الهاتف",
  "Pick a channel": "اختر قناة",
  "Pick a group that isn't ticked; the ticked ones go into it.": "اختر مجموعة غير محددة؛ وستُنقل المحددة إليها.",
  "Pick a release to go back to.  It's checked like an update (its fingerprint and TiviBro's signature) and installed through the Homebrew Channel.  Before that, everything TiviBro keeps on this TV (settings, channel edits, favorites, reminders) is saved, and a restore point is made.  Recordings, your playlist and My media stay as they are.  Automatic update checks turn off, so the newer version isn't offered straight back.": "اختر إصدارًا للرجوع إليه.  يُفحص مثل التحديث (بصمته وتوقيع TiviBro) ويُثبَّت عبر Homebrew Channel.  قبل ذلك يُحفظ كل ما يخزنه TiviBro على هذا التلفزيون (الإعدادات وتعديلات القنوات والمفضلة والتذكيرات) وتُنشأ نقطة استعادة.  تبقى التسجيلات وقائمة التشغيل ووسائطي كما هي.  يتوقف الفحص التلقائي للتحديثات، فلا يُعرض عليك الإصدار الأحدث مباشرة.",
  "Pick a share first.": "اختر مشاركة أولًا.",
  "Pick of the day": "اختيار اليوم",
  "Pick the other version": "اختر النسخة الأخرى",
  "Pick which ticked group the others go into.": "اختر المجموعة المحددة التي ستُدمج فيها المجموعات الأخرى.",
  "Picks the 5.1 or Dolby track when there is one in that language.  Your soundbar or TV needs to support it.": "يختار مسار 5.1 أو Dolby عند توفره بتلك اللغة.  يجب أن يدعم ذلك مكبّر الصوت الشريطي أو التلفزيون.",
