  "Plays the channel you rest on in a corner window.": "يعرض القناة التي تتوقف عندها في نافذة صغيرة في الزاوية.",
  "Plays the channel you rest on.  Turn off on very slow TVs for the snappiest list.": "يعرض القناة التي تتوقف عندها.  أوقفه على أجهزة التلفزيون البطيئة جدًا للحصول على قائمة أسرع.",
  "Plex": "Plex",
