  "Plex leaves the menu, the phone app and the web editor until you sign in again.": "يختفي Plex من القائمة وتطبيق الهاتف ومحرر الويب حتى تسجّل الدخول مرة أخرى.",
  "Plex looks them up online for this title": "يبحث Plex عنها عبر الإنترنت لهذا العنوان",
