  "Poster size": "حجم الملصق",
  "Poster size:": "حجم الملصق:",
  "Posters and details for titles without them": "ملصقات وتفاصيل للعناوين التي لا تتوفر لها",
  "Posters, details, episodes, trailers and skip times for shows: in the guide, your provider's Shows, My media and Up next.  TMDB needs your token.  TheTVDB needs nothing: it comes through TiviBro's own service, and only titles leave the TV.  Metadata provided by TheTVDB (thetvdb.com).": "ملصقات وتفاصيل وحلقات وإعلانات تشويقية وأوقات التخطي للمسلسلات: في الدليل، وفي مسلسلات مزوّدك، ووسائطي، والتالي.  يحتاج TMDB إلى الرمز الخاص بك.  أما TheTVDB فلا يحتاج إلى شيء: يعمل عبر خدمة TiviBro نفسها، ولا يغادر التلفزيون سوى العناوين.  البيانات الوصفية مقدَّمة من TheTVDB (thetvdb.com).",
  "Posters, details, trailers and skip times for movies: in the guide (Movies on now), your provider's Movies and My media.  TMDB needs your token.  TheTVDB needs nothing: it comes through TiviBro's own service, and only titles leave the TV.  Metadata provided by TheTVDB (thetvdb.com).": "ملصقات وتفاصيل وإعلانات تشويقية وأوقات التخطي للأفلام: في الدليل (أفلام تعرض الآن)، وفي أفلام مزوّدك، ووسائطي.  يحتاج TMDB إلى الرمز الخاص بك.  أما TheTVDB فلا يحتاج إلى شيء: يعمل عبر خدمة TiviBro نفسها، ولا يغادر التلفزيون سوى العناوين.  البيانات الوصفية مقدَّمة من TheTVDB (thetvdb.com).",
  "Posters, full screen": "الملصقات بملء الشاشة",
  "Prefer surround sound": "تفضيل الصوت المحيطي",
  "Preferred source for every show": "المصدر المفضل لكل مسلسل",
  "Press Back again to exit": "اضغط رجوع مرة أخرى للخروج",
  "Press Back twice to exit": "اضغط رجوع مرتين للخروج",
  "Press OK to search Plex": "اضغط OK للبحث في Plex",
