  "Press the button to learn": "اضغط الزر ليتعلمه التطبيق",
  "Preview first works like TiviMate: the first OK plays it in the corner window, the second goes fullscreen.": "المعاينة أولًا تعمل مثل TiviMate: أول ضغطة على OK تشغّل القناة في النافذة الصغيرة، والثانية تعرضها بملء الشاشة.",
  "Preview first, then fullscreen": "معاينة أولًا ثم ملء الشاشة",
