  "Reachable, but this TV can only unzip .gz guides through the network helper.  Set Settings > Playback > Connection to Automatic, or use the plain .xml address.": "يمكن الوصول إليه، لكن هذا التلفزيون لا يفك ضغط أدلة .gz إلا عبر مساعد الشبكة.  اضبط الإعدادات > التشغيل > الاتصال على تلقائي، أو استخدم عنوان .xml العادي.",
