  "Record (●)": "تسجيل (●)",
  "Record to": "التسجيل في",
  "Record to a USB drive on a rooted TV, or to a network share on any TV.  webOS keeps USB drives from apps installed in developer mode; on a rooted TV (the Homebrew Channel) TiviBro's helper reaches them.  A network share works without root: a Windows or Samba share (a PC, Mac, NAS or router) or WebDAV (Synology, QNAP, TrueNAS, Unraid, Nextcloud).  Add it as a library in My media, then choose it below.  Live pause then goes there too, for hours.  Without either, live pause keeps up to 10 minutes in the TV's own storage.": "سجّل على قرص USB في تلفزيون مفتوح الصلاحيات (root)، أو على مشاركة شبكة في أي تلفزيون.  يمنع webOS التطبيقات المثبّتة في وضع المطوّر من الوصول إلى أقراص USB؛ وفي تلفزيون root (عبر Homebrew Channel) يصل إليها مساعد TiviBro.  تعمل مشاركة الشبكة دون root: مشاركة Windows أو Samba (كمبيوتر أو Mac أو NAS أو راوتر) أو WebDAV (Synology وQNAP وTrueNAS وUnraid وNextcloud).  أضفها كمكتبة في وسائطي ثم اخترها أدناه.  وسيُحفظ إيقاف البث المباشر مؤقتًا هناك أيضًا، لساعات.  وبدون أي منهما، يحتفظ إيقاف البث المباشر مؤقتًا بما يصل إلى 10 دقائق في مساحة التلفزيون نفسه.",
  "Record to a share on your network (a PC, Mac or NAS): no USB drive or root needed.  Choose one of your My media libraries on a Windows share or WebDAV.  Live pause goes there too.": "سجّل على مشاركة في شبكتك (كمبيوتر أو Mac أو NAS) دون الحاجة إلى قرص USB أو root.  اختر إحدى مكتبات وسائطي على مشاركة Windows أو WebDAV.  وسيُحفظ إيقاف البث المباشر مؤقتًا هناك أيضًا.",
