  "Saved.  The TV makes this change when TiviBro is next on screen.": "تم الحفظ.  يطبّق التلفزيون هذا التغيير عند ظهور TiviBro على الشاشة في المرة التالية.",
  "Saved.  Your channels change when you leave this page.": "تم الحفظ.  تتغير قنواتك عند مغادرة هذه الصفحة.",
  "Saving your settings, then installing {v}…": "جارٍ حفظ إعداداتك، ثم تثبيت {v}…",
  "Scan a QR code: your phone fills in a GitHub issue with this TV's details and log, logins and server names taken out.  In the phone app it opens the report page there.": "امسح رمز QR: يملأ هاتفك مشكلة على GitHub بتفاصيل هذا التلفزيون وسجله، بعد حذف بيانات الدخول وأسماء الخوادم.  وفي تطبيق الهاتف يفتح صفحة الإبلاغ هناك.",
  "Scan a code with your phone: Smart clean-up, renaming, sorting and backups with a real keyboard.": "امسح رمزًا بهاتفك: التنظيف الذكي وإعادة التسمية والترتيب والنسخ الاحتياطية بلوحة مفاتيح حقيقية.",
