  "Scan the code with your phone's camera (or open the address on a computer).  Describe what happened there; the TV adds its version, model and log, with logins and server names taken out, and your phone opens a GitHub issue ready to send.": "امسح الرمز بكاميرا هاتفك (أو افتح العنوان على حاسوب).  صف ما حدث هناك؛ يضيف التلفزيون إصداره وطرازه وسجله، بعد حذف بيانات الدخول وأسماء الخوادم، ويفتح هاتفك مشكلة على GitHub جاهزة للإرسال.",
  "Scan the code with your phone's camera, or open the address on a computer on the same network.  Rename, hide, sort and clean up with a real keyboard; changes show up here as you send them.": "امسح الرمز بكاميرا هاتفك، أو افتح العنوان على حاسوب في الشبكة نفسها.  أعد التسمية وأخفِ ورتّب ونظّف بلوحة مفاتيح حقيقية؛ تظهر التغييرات هنا فور إرسالها.",
