  "Search TMDB for movie details?  The movie title is sent to TMDB using your saved token.  Images load from image.tmdb.org.": "هل تريد البحث في TMDB عن تفاصيل الفيلم؟  يُرسل عنوان الفيلم إلى TMDB باستخدام الرمز المحفوظ لديك.  تُحمَّل الصور من image.tmdb.org.",
  "Search TMDB for this show?  Its title is sent to TMDB using your saved token.": "هل تريد البحث في TMDB عن هذا المسلسل؟  يُرسل عنوانه إلى TMDB باستخدام الرمز المحفوظ لديك.",
