  "Some movies have only sound this TV can't decode: DTS on LG TVs from 2020 to 2022, Dolby TrueHD on every LG TV, and FLAC surround.  Automatic turns that sound into Dolby Digital while the movie plays, with a small audio converter kept on the TV.  The picture is not touched.  Off plays them as they are, often without sound.": "بعض الأفلام فيها صوت لا يستطيع هذا التلفزيون فك ترميزه فقط: DTS على تلفزيونات LG من 2020 إلى 2022، وDolby TrueHD على كل تلفزيونات LG، وFLAC المحيطي.  يحوّل الخيار تلقائي هذا الصوت إلى Dolby Digital أثناء تشغيل الفيلم، بواسطة محوّل صوت صغير على التلفزيون.  الصورة لا تتغير.  أما الإيقاف فيشغّلها كما هي، وغالبًا بلا صوت.",
