  "That isn't a DNS address (192.168.1.1, 2001:de4::101) or an https:// link": "هذا ليس عنوان DNS (192.168.1.1، 2001:de4::101) ولا رابط https://",
  "That isn't a server name or address.  Try its name (like NAS or DESKTOP-PC) or its IP address.": "هذا ليس اسم خادم أو عنوانه.  جرّب اسمه (مثل NAS أو DESKTOP-PC) أو عنوان IP الخاص به.",
  "That isn't a service account key.": "هذا ليس مفتاح حساب خدمة.",
