  "View app log": "عرض سجل التطبيق",
  "View app log with earlier sessions": "عرض سجل التطبيق مع الجلسات السابقة",
  "View network helper log": "عرض سجل مساعد الشبكة",
  "Voices clearer over music and effects: what both speakers share (where voices are) is lifted, the low boom trimmed and the voice band brought forward.  While it's on, the sound goes through the audio converter and comes back as stereo Dolby Digital: a channel takes a second or two longer to start, the rewind buffer isn't used, and sound isn't sent straight to a soundbar (passthrough).": "أصوات أوضح فوق الموسيقى والمؤثرات: يتم رفع ما تشترك فيه السماعتان (حيث تكون الأصوات)، وتقليل الدوي المنخفض، وإبراز نطاق الصوت البشري.  أثناء التشغيل يمر الصوت عبر محوّل الصوت ويعود بصيغة Dolby Digital ستيريو: تحتاج القناة إلى ثانية أو ثانيتين إضافيتين لتبدأ، ولا يُستخدم مخزن الرجوع، ولا يُرسل الصوت مباشرة إلى مكبّر الصوت (passthrough).",
  "Wait for the media rescan to finish, then press Yellow.": "انتظر حتى ينتهي فحص الوسائط من جديد، ثم اضغط Yellow.",
