  "Watch someone talking.  Hear the words before the lips move?  ▶ makes the sound later.  Lips move before you hear them?  ◀ makes it earlier.": "شاهد شخصًا يتحدث.  هل تسمع الكلمات قبل أن تتحرك الشفاه؟  ▶ يؤخر الصوت.  هل تتحرك الشفاه قبل أن تسمعها؟  ◀ يقدّم الصوت.",
  "Watch the channel now": "شاهد القناة الآن",
