  "Watching now": "يُشاهد الآن",
  "Watchlist finds and the like wait while a movie or episode plays full screen, and show when you stop or leave full screen.  Reminders you set still come on time.": "ما تجده قائمة المشاهدة وما شابه ينتظر أثناء تشغيل فيلم أو حلقة بملء الشاشة، ويظهر عند الإيقاف أو الخروج من ملء الشاشة.  أما التذكيرات التي ضبطتها فتأتي في موعدها.",
  "Watchlist row": "صف قائمة المشاهدة",
  "Web editor  ·  any browser": "محرر الويب  ·  أي متصفح",
